import React, { useState, useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import Header from '../components/Header';
import Footer from '../components/Footer';
import CounterAnimation from '../components/CounterAnimation';

const DenturesCourse = () => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    country: '',
    education: '',
    experience: '',
    courseType: 'clinical'
  });

  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-out-cubic',
      offset: 50,
      once: true
    });
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    alert('Thank you for your enrollment! We will contact you shortly.');
  };

  const courseModules = [
    {
      module: "Module 1: Denture Fundamentals",
      topics: ["Anatomy & Physiology", "Oral Examination", "Patient Assessment", "Treatment Planning"]
    },
    {
      module: "Module 2: Complete Dentures",
      topics: ["Primary Impressions", "Secondary Impressions", "Jaw Relations", "Try-in Procedures"]
    },
    {
      module: "Module 3: Partial Dentures",
      topics: ["Classification Systems", "Design Principles", "Surveying Techniques", "Framework Design"]
    },
    {
      module: "Module 4: Digital Integration",
      topics: ["Digital Impressions", "CAD/CAM Dentures", "Virtual Design", "3D Printing"]
    },
    {
      module: "Module 5: Advanced Techniques",
      topics: ["Implant-Supported Dentures", "Attachment Systems", "Soft Liners", "Relines & Repairs"]
    },
    {
      module: "Module 6: Patient Management",
      topics: ["Delivery & Adjustment", "Follow-up Care", "Troubleshooting", "Long-term Maintenance"]
    }
  ];

  const courseFeatures = [
    {
      icon: "🦷",
      title: "Complete Denture Training",
      description: "Comprehensive education in complete and partial dentures"
    },
    {
      icon: "🎥",
      title: "Clinical Procedures",
      description: "120+ hours of denture fabrication and fitting"
    },
    {
      icon: "🔬",
      title: "Digital Workflows",
      description: "Modern CAD/CAM denture techniques"
    },
    {
      icon: "👨‍⚕️",
      title: "Expert Prosthodontists",
      description: "Learn from leading denture specialists"
    },
    {
      icon: "💻",
      title: "3D Technology",
      description: "Digital design and manufacturing"
    },
    {
      icon: "🏆",
      title: "Professional Certification",
      description: "Specialized denture therapy certification"
    }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />
      
      {/* Hero Section with Crystal Glass Architecture Design */}
      <section className="relative min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900 text-white overflow-hidden">
        {/* Crystal Pattern Background */}
        <div className="absolute inset-0">
          <div className="absolute top-1/4 left-1/4 w-72 h-72 bg-gradient-to-br from-blue-400/20 to-cyan-400/20 rounded-full blur-3xl transform rotate-45"></div>
          <div className="absolute bottom-1/4 right-1/4 w-64 h-64 bg-gradient-to-br from-purple-400/30 to-pink-400/30 rounded-full blur-3xl transform -rotate-45"></div>
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-gradient-to-br from-emerald-400/15 to-teal-400/15 rounded-full blur-3xl"></div>
        </div>

        {/* Glass Morphism Overlay */}
        <div className="absolute inset-0">
          <div className="absolute top-20 left-20 w-32 h-32 bg-white/10 backdrop-blur-xl rounded-3xl border border-white/20 transform rotate-12 animate-float"></div>
          <div className="absolute bottom-32 right-20 w-24 h-24 bg-white/5 backdrop-blur-xl rounded-2xl border border-white/10 transform -rotate-12 animate-float" style={{animationDelay: '1s'}}></div>
          <div className="absolute top-1/3 right-1/3 w-20 h-20 bg-white/15 backdrop-blur-xl rounded-xl border border-white/30 transform rotate-45 animate-float" style={{animationDelay: '2s'}}></div>
        </div>

        {/* Geometric Pattern */}
        <div className="absolute inset-0 opacity-10">
          <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
            <defs>
              <pattern id="crystal-pattern" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
                <polygon points="10,0 20,10 10,20 0,10" fill="rgba(255,255,255,0.1)" stroke="rgba(255,255,255,0.2)" strokeWidth="0.5"/>
              </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#crystal-pattern)" />
          </svg>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-32 pb-20">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            {/* Content Side */}
            <div data-aos="fade-right">
              <div className="inline-flex items-center px-6 py-3 rounded-full bg-white/10 backdrop-blur-sm border border-white/20 mb-8">
                <div className="w-3 h-3 bg-gradient-to-r from-blue-400 to-cyan-400 rounded-full mr-3 animate-pulse"></div>
                <span className="text-sm font-medium">Professional Denture Training</span>
              </div>
              
              <h1 className="text-5xl md:text-7xl font-bold mb-8 leading-tight">
                <span className="block bg-gradient-to-r from-blue-400 via-cyan-400 to-teal-400 bg-clip-text text-transparent">
                  Complete
                </span>
                <span className="block text-white">Dentures</span>
                <span className="block bg-gradient-to-r from-purple-400 via-pink-400 to-rose-400 bg-clip-text text-transparent">
                  Mastery
                </span>
              </h1>
              
              <p className="text-xl md:text-2xl mb-10 text-gray-300 leading-relaxed">
                Master the art of complete and partial denture fabrication with precision techniques and patient-centered care approaches.
              </p>

              {/* Glass Morphism Stats */}
              <div className="grid grid-cols-2 gap-6 mb-10">
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-6 border border-white/20 hover:bg-white/15 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-cyan-400 mb-2">
                    <CounterAnimation end={200} duration={2000} />+
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors">Denture Cases</p>
                </div>
                <div className="bg-white/10 backdrop-blur-xl rounded-2xl p-6 border border-white/20 hover:bg-white/15 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-purple-400 mb-2">
                    <CounterAnimation end={4} duration={1500} />
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors">Months Training</p>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4">
                <button className="px-8 py-4 bg-gradient-to-r from-blue-500 to-cyan-600 rounded-xl font-semibold text-white hover:from-blue-600 hover:to-cyan-700 transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-blue-500/25">
                  Enroll Today
                </button>
                <button className="px-8 py-4 bg-white/10 backdrop-blur-xl rounded-xl font-semibold text-white border border-white/20 hover:bg-white/20 transition-all duration-300">
                  Course Details
                </button>
              </div>
            </div>

            {/* Visual Side - Crystal Glass Architecture */}
            <div className="relative" data-aos="fade-left">
              <div className="relative w-full h-96 lg:h-[500px]">
                {/* Main Crystal Structure */}
                <div className="absolute inset-0 bg-gradient-to-br from-white/20 to-white/5 backdrop-blur-xl rounded-3xl border border-white/30 shadow-2xl transform rotate-3 hover:rotate-1 transition-transform duration-700">
                  <div className="absolute inset-4 bg-gradient-to-br from-white/10 to-transparent rounded-2xl border border-white/20">
                    <div className="p-8 h-full flex flex-col justify-center items-center text-center">
                      <div className="w-20 h-20 bg-gradient-to-br from-cyan-400 to-blue-500 rounded-full mb-6 flex items-center justify-center">
                        <svg className="w-10 h-10 text-white" fill="currentColor" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M3 4a1 1 0 011-1h12a1 1 0 011 1v2a1 1 0 01-1 1H4a1 1 0 01-1-1V4zm0 4a1 1 0 011-1h6a1 1 0 011 1v6a1 1 0 01-1 1H4a1 1 0 01-1-1V8zm8 0a1 1 0 011-1h4a1 1 0 011 1v2a1 1 0 01-1 1h-4a1 1 0 01-1-1V8z" clipRule="evenodd" />
                        </svg>
                      </div>
                      <h3 className="text-2xl font-bold text-white mb-4">Precision Craftsmanship</h3>
                      <p className="text-gray-300">Learn advanced techniques for perfect denture fit and aesthetics</p>
                    </div>
                  </div>
                </div>

                {/* Floating Crystal Elements */}
                <div className="absolute -top-8 -left-8 w-16 h-16 bg-gradient-to-br from-purple-500/60 to-pink-500/60 backdrop-blur-xl rounded-xl border border-white/30 animate-float transform rotate-45"></div>
                <div className="absolute -bottom-8 -right-8 w-20 h-20 bg-gradient-to-br from-blue-500/60 to-cyan-500/60 backdrop-blur-xl rounded-2xl border border-white/30 animate-float" style={{animationDelay: '1s'}}></div>
                <div className="absolute top-1/4 -right-12 w-12 h-12 bg-gradient-to-br from-emerald-500/60 to-teal-500/60 backdrop-blur-xl rounded-lg border border-white/30 animate-float transform rotate-12" style={{animationDelay: '2s'}}></div>
                <div className="absolute bottom-1/3 -left-10 w-14 h-14 bg-gradient-to-br from-yellow-500/60 to-orange-500/60 backdrop-blur-xl rounded-xl border border-white/30 animate-float transform -rotate-12" style={{animationDelay: '0.5s'}}></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Course Features with Crystal Glass Theme */}
      <section className="py-20 bg-gradient-to-b from-gray-50 to-white relative overflow-hidden">
        {/* Crystal Background Elements */}
        <div className="absolute inset-0 opacity-5">
          <div className="absolute top-10 left-10 w-64 h-64 bg-gradient-to-br from-blue-500 to-cyan-500 rounded-full blur-3xl transform rotate-45"></div>
          <div className="absolute bottom-10 right-10 w-48 h-48 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full blur-3xl transform -rotate-45"></div>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
          <div className="text-center mb-16" data-aos="fade-up">
            <h2 className="text-4xl md:text-5xl font-bold mb-6">
              <span className="bg-gradient-to-r from-blue-600 via-cyan-600 to-purple-600 bg-clip-text text-transparent">
                Crystal Clear Excellence
              </span>
            </h2>
            <p className="text-xl text-gray-600 max-w-3xl mx-auto">
              Discover our comprehensive denture training program designed with precision and clarity in mind.
            </p>
          </div>

          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
            {/* Feature Card 1 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="100">
              <div className="absolute inset-0 bg-gradient-to-br from-blue-500/10 to-cyan-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-blue-500 to-cyan-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19.428 15.428a2 2 0 00-1.022-.547l-2.387-.477a6 6 0 00-3.86.517l-.318.158a6 6 0 01-3.86.517L6.05 15.21a2 2 0 00-1.806.547M8 4h8l-1 1v5.172a2 2 0 00.586 1.414l5 5c1.26 1.26.367 3.414-1.415 3.414H4.828c-1.782 0-2.674-2.154-1.414-3.414l5-5A2 2 0 009 10.172V5L8 4z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-blue-600 transition-colors">Laboratory Techniques</h3>
                <p className="text-gray-600 leading-relaxed">Master precision laboratory procedures for complete and partial denture fabrication.</p>
              </div>
            </div>

            {/* Feature Card 2 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="200">
              <div className="absolute inset-0 bg-gradient-to-br from-purple-500/10 to-pink-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-purple-500 to-pink-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-purple-600 transition-colors">Patient Care</h3>
                <p className="text-gray-600 leading-relaxed">Learn comprehensive patient management and communication skills for denture patients.</p>
              </div>
            </div>

            {/* Feature Card 3 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="300">
              <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/10 to-teal-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-emerald-600 transition-colors">Clinical Excellence</h3>
                <p className="text-gray-600 leading-relaxed">Achieve superior clinical outcomes with evidence-based denture protocols.</p>
              </div>
            </div>

            {/* Feature Card 4 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="400">
              <div className="absolute inset-0 bg-gradient-to-br from-yellow-500/10 to-orange-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-yellow-500 to-orange-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.746 0 3.332.477 4.5 1.253v13C19.832 18.477 18.246 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-orange-600 transition-colors">Advanced Materials</h3>
                <p className="text-gray-600 leading-relaxed">Work with the latest denture materials and innovative fabrication techniques.</p>
              </div>
            </div>

            {/* Feature Card 5 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="500">
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-500/10 to-blue-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-indigo-500 to-blue-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-indigo-600 transition-colors">Quick Adjustments</h3>
                <p className="text-gray-600 leading-relaxed">Learn rapid adjustment techniques for immediate denture comfort and fit.</p>
              </div>
            </div>

            {/* Feature Card 6 */}
            <div className="group relative" data-aos="fade-up" data-aos-delay="600">
              <div className="absolute inset-0 bg-gradient-to-br from-rose-500/10 to-pink-500/10 rounded-3xl blur-xl transform group-hover:scale-110 transition-transform duration-300"></div>
              <div className="relative bg-white/60 backdrop-blur-xl rounded-3xl p-8 border border-white/30 shadow-xl hover:shadow-2xl transition-all duration-300 transform group-hover:-translate-y-2">
                <div className="w-16 h-16 bg-gradient-to-br from-rose-500 to-pink-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform duration-300">
                  <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
                  </svg>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-4 group-hover:text-rose-600 transition-colors">Patient Satisfaction</h3>
                <p className="text-gray-600 leading-relaxed">Achieve exceptional patient satisfaction through quality denture care and service.</p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Course Modules */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Curriculum
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive modules covering all aspects of denture therapy
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseModules.map((module, index) => (
              <div 
                key={index} 
                className="bg-white rounded-lg p-6 shadow-lg hover:shadow-xl transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <h3 className="text-xl font-semibold text-purple-800 mb-4">{module.module}</h3>
                <ul className="space-y-2">
                  {module.topics.map((topic, topicIndex) => (
                    <li key={topicIndex} className="flex items-start">
                      <span className="text-purple-600 mr-2">•</span>
                      <span className="text-gray-700">{topic}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>



      {/* Enrollment Form */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Enroll Now
            </h2>
            <p className="text-xl text-gray-600">
              Start your journey in denture therapy today
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-lg p-8" data-aos="fade-up">
            <form onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    First Name
                  </label>
                  <input
                    type="text"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-purple-500 focus:border-purple-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Last Name
                  </label>
                  <input
                    type="text"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-purple-500 focus:border-purple-500"
                    required
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-purple-500 focus:border-purple-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Phone
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-purple-500 focus:border-purple-500"
                    required
                  />
                </div>
              </div>
              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Country
                </label>
                <input
                  type="text"
                  name="country"
                  value={formData.country}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-purple-500 focus:border-purple-500"
                  required
                />
              </div>
              <div className="text-center">
                <button
                  type="submit"
                  className="bg-purple-600 text-white py-3 px-8 rounded-lg font-semibold hover:bg-purple-700 transition duration-200"
                >
                  Enroll Now
                </button>
                <p className="text-sm text-gray-600 mt-4">
                  For course details and pricing, call us at +91 7889093147
                </p>
              </div>
            </form>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default DenturesCourse;
