// Animated Stat Counter Component
const StatCounter = ({ start, end, duration, suffix, label }) => {
  const [count, setCount] = useState(start);
  const [isVisible, setIsVisible] = useState(false);
  const counterRef = useRef(null);

  useEffect(() => {
    const observer = new window.IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isVisible) {
          setIsVisible(true);
        }
      },
      { threshold: 0.1 }
    );
    if (counterRef.current) observer.observe(counterRef.current);
    return () => { if (counterRef.current) observer.unobserve(counterRef.current); };
  }, [isVisible]);

  useEffect(() => {
    if (!isVisible) return;
    let startTime;
    const animate = (currentTime) => {
      if (!startTime) startTime = currentTime;
      const progress = Math.min((currentTime - startTime) / duration, 1);
      const easeOutCubic = 1 - Math.pow(1 - progress, 3);
      const currentCount = Math.floor(start + (end - start) * easeOutCubic);
      setCount(currentCount);
      if (progress < 1) requestAnimationFrame(animate);
    };
    requestAnimationFrame(animate);
  }, [isVisible, start, end, duration]);

  return (
    <div ref={counterRef} className="bg-white/20 backdrop-blur-sm rounded-lg px-6 py-3 mx-2">
      <span className="text-2xl font-bold">{count}{suffix}</span>
      <p className="text-sm">{label}</p>
    </div>
  );
};

