import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";
import logo from "../assets/Logo.png";

const navLinks = [
  { 
    name: "Home", 
    path: "/", // Main home path
    hasDropdown: true,
    dropdownItems: [
      { name: "About Us", path: "/about-us" },
      { name: "Faculty", path: "/faculty" },
    ]
  },
  { 
    name: "Licensing Exam", 
    path: null, // No direct path, only dropdown
    hasDropdown: true,
    dropdownItems: [
      { name: "ADC PART 1 PREPARATION", path: "/adc-exam" },
      { name: "INBDE EXAM PREPARATION", path: "/inbde-exam" },
      { name: "AFK EXAM PREPARATION", path: "/afk-exam" },
      { name: "DHA EXAM PREPARATION", path: "/dha-exam" },
      { name: "MOH EXAM PREPARATION", path: "/moh-exam" },
      { name: "HAAD EXAM PREPARATION", path: "/haad-exam" },
      { name: "ORE PART 1 PREPARATION", path: "/ore-part1-exam" },
    ]
  },
  { 
    name: "Clinical Courses", 
    path: null, // No direct path, only dropdown
    hasDropdown: true,
    isScrollable: true,
    dropdownItems: [
      { name: "Endodontics Course", path: "/endodontics-course" },
      { name: "Oral Surgery Course", path: "/oral-surgery-course" },
      { name: "Orthodontics Course", path: "/orthodontics-course" },
      { name: "Periodontics Course", path: "/periodontics-course" },
      { name: "Prosthodontics Course", path: "/prosthodontics-course" },
      { name: "Oral Pathology Course", path: "/oral-pathology-course" },
      { name: "Pediatric Dentistry Course", path: "/pediatric-dentistry-course" },
      { name: "Oral Medicine Course", path: "/oral-medicine-course" },
      { name: "Dental Implantology Course", path: "/dental-implantology-course" },
      { name: "Cosmetic Dentistry Course", path: "/cosmetic-dentistry-course" },
      { name: "Dental Radiology Course", path: "/dental-radiology-course" },
      { name: "Emergency Dentistry Course", path: "/emergency-dentistry-course" },
      { name: "Online Implant Dentistry Course", path: "/online-implant-dentistry-course" },
      { name: "Basal Implant Course", path: "/basal-implant-course" },
      { name: "Fixed Prosthodontics Course", path: "/fixed-prosthodontics-course" },
      { name: "Restorative Dentistry Course", path: "/restorative-dentistry-course" },
      { name: "Implant Dentistry Course", path: "/implant-dentistry-course" },
      { name: "Dentures Course", path: "/dentures-course" },
      { name: "Aesthetic Dentistry Course", path: "/aesthetic-dentistry-course" },
      { name: "General Dentistry Course", path: "/general-dentistry-course" },
      { name: "Laser Dentistry Course", path: "/laser-dentistry-course" },
      { name: "Periodontology Course", path: "/periodontology-course" },
      { name: "Treatment Planning Course", path: "/treatment-planning-course" },
      { name: "Pedodontics Course", path: "/pedodontics-course" },
      { name: "Medical Emergencies Course", path: "/medical-emergencies-course" },
      { name: "Digital Dentistry Course", path: "/digital-dentistry-course" },
      { name: "Operative Dental Course", path: "/operative-dental-course" },
    ]
  },
  { 
    name: "Support Dentistry", 
    path: null, // No direct path, only dropdown
    hasDropdown: true,
    dropdownItems: [
      { name: "Dental Assistant", path: "/dentist-assistant-course" },
      { name: "Dental Hygienist", path: "/dental-hygienist-course" },
      { name: "Dental Therapist", path: "/dental-therapist-course" },
    ]
  },
  { name: "Reviews", path: "/highlights" },
  { name: "Videos", path: "/videos" },
  { name: "Q & A", path: "/qa" },
];

const Header = () => {
  const location = useLocation();
  const [hoveredDropdown, setHoveredDropdown] = useState(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const toggleDropdown = (linkName) => {
    setHoveredDropdown(hoveredDropdown === linkName ? null : linkName);
  };

  const closeDropdown = () => {
    setHoveredDropdown(null);
  };

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <header className="w-full flex flex-col items-center py-2 sm:py-4 bg-white border-b border-[#D9D9D9] sticky top-0 z-50">
      <div className="flex flex-col lg:flex-row items-center justify-center w-full px-4 sm:px-6">
        <div className="flex items-center justify-between w-full lg:w-auto">
          <div className="flex items-center">
            <img src={logo} alt="Master Clinical Dentistry Logo" className="w-12 h-12 sm:w-16 sm:h-16 lg:w-20 lg:h-20 lg:mr-4" />
            <h1 className="text-sm sm:text-lg md:text-2xl lg:text-3xl xl:text-4xl font-extrabold text-[#0A1F44] tracking-wide text-center lg:text-left ml-2 lg:ml-0">
              <span className="block sm:inline">MASTER CLINICAL</span>
              <span className="block sm:inline"> DENTISTRY INSTITUTE</span>
            </h1>
          </div>
          
          {/* Mobile menu button */}
          <button 
            className="lg:hidden p-2 rounded-md border border-[#D9D9D9] bg-white hover:bg-gray-50"
            onClick={toggleMobileMenu}
          >
            <svg className="w-6 h-6 text-[#0A1F44]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              {isMobileMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>
        
        {/* Phone number - hidden on small screens */}
        <div className="hidden lg:flex items-center ml-0 lg:ml-8 mt-2 lg:mt-0">
          <svg className="w-8 h-12 lg:w-10 lg:h-14 text-[#008080] mr-1" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M4.71922 0.5H2.5C1.39543 0.5 0.5 1.39543 0.5 2.5V4.5C0.5 10.0228 4.97715 14.5 10.5 14.5H12.5C13.6046 14.5 14.5 13.6046 14.5 12.5V11.118C14.5 10.7393 14.286 10.393 13.9472 10.2236L11.5313 9.01564C10.987 8.74349 10.3278 9.01652 10.1354 9.59384L9.83762 10.4871C9.64474 11.0658 9.05118 11.4102 8.45309 11.2906C6.05929 10.8119 4.18814 8.94071 3.70938 6.54691C3.58976 5.94882 3.93422 5.35526 4.51286 5.16238L5.62149 4.79284C6.11721 4.6276 6.40214 4.10855 6.2754 3.60162L5.68937 1.25746C5.57807 0.812297 5.17809 0.5 4.71922 0.5Z" stroke="currentColor"/>
          </svg>
          <span className="text-base lg:text-xl font-bold text-[#0A1F44]">+91-7889093147 <span className="font-normal text-[#6B7280]">(India)</span></span>
        </div>
      </div>
      
      {/* Desktop Navigation */}
      <nav className="hidden lg:flex mt-4 lg:mt-6 w-full justify-center flex-wrap gap-1 relative px-4">
        {navLinks.map((link) => (
          <div 
            key={link.name}
            className="relative"
          >
            {link.hasDropdown ? (
              // For dropdown items with main path (like Home), render as Link with dropdown
              link.path ? (
                <div className="flex">
                  <Link
                    to={link.path}
                    className={`flex items-center px-4 py-3 font-semibold transition-all duration-300 text-sm lg:text-base relative overflow-hidden group ${
                      location.pathname === link.path 
                        ? "text-white" 
                        : "text-[#0A1F44] hover:text-white"
                    }`}
                    style={{ minWidth: 100 }}
                    onClick={closeDropdown}
                  >
                    {/* Active/hover background */}
                    <div className={`absolute inset-0 bg-gradient-to-r from-[#008080] to-[#20B2AA] transition-all duration-300 ${
                      location.pathname === link.path 
                        ? "opacity-100 scale-100" 
                        : "opacity-0 scale-95 group-hover:opacity-100 group-hover:scale-100"
                    }`} style={{ borderRadius: '12px 0 0 12px' }}></div>
                    
                    <span className="relative z-10 truncate">{link.name}</span>
                  </Link>
                  <button
                    className={`flex items-center px-2 py-3 font-semibold transition-all duration-300 text-sm lg:text-base cursor-pointer relative overflow-hidden group ${
                      hoveredDropdown === link.name 
                        ? "text-white"
                        : "text-[#0A1F44] hover:text-white"
                    }`}
                    onClick={() => toggleDropdown(link.name)}
                  >
                    {/* Modern gradient background */}
                    <div className={`absolute inset-0 bg-gradient-to-r from-[#008080] to-[#20B2AA] transition-all duration-300 ${
                      hoveredDropdown === link.name || location.pathname === link.path
                        ? "opacity-100 scale-100" 
                        : "opacity-0 scale-95 group-hover:opacity-100 group-hover:scale-100"
                    }`} style={{ borderRadius: '0 12px 12px 0' }}></div>
                    
                    <svg 
                      className={`w-4 h-4 transition-all duration-300 relative z-10 ${
                        hoveredDropdown === link.name ? 'rotate-180 text-white' : 'group-hover:text-white'
                      }`} 
                      fill="none" 
                      stroke="currentColor" 
                      viewBox="0 0 24 24"
                    >
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                    </svg>
                  </button>
                </div>
              ) : (
                // For dropdown items without main path, render as button
                <button
                  className={`flex items-center px-6 py-3 font-semibold transition-all duration-300 text-sm lg:text-base cursor-pointer relative overflow-hidden group ${
                    hoveredDropdown === link.name 
                      ? "text-white"
                      : "text-[#0A1F44] hover:text-white"
                  }`}
                  style={{ minWidth: 120 }}
                  onClick={() => toggleDropdown(link.name)}
                >
                  {/* Modern gradient background */}
                  <div className={`absolute inset-0 bg-gradient-to-r from-[#008080] to-[#20B2AA] transition-all duration-300 ${
                    hoveredDropdown === link.name 
                      ? "opacity-100 scale-100" 
                      : "opacity-0 scale-95 group-hover:opacity-100 group-hover:scale-100"
                  }`} style={{ borderRadius: '12px' }}></div>
                  
                  {/* Hover effect background */}
                  <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 transition-opacity duration-300" style={{ borderRadius: '12px' }}></div>
                  
                  <span className="relative z-10 truncate">{link.name}</span>
                  <svg 
                    className={`w-4 h-4 ml-2 transition-all duration-300 relative z-10 ${
                      hoveredDropdown === link.name ? 'rotate-180 text-white' : 'group-hover:text-white'
                    }`} 
                    fill="none" 
                    stroke="currentColor" 
                    viewBox="0 0 24 24"
                  >
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                  </svg>
                </button>
              )
            ) : (
              // Regular navigation links
              <Link
                to={link.path}
                className={`flex items-center px-6 py-3 font-semibold transition-all duration-300 text-sm lg:text-base relative overflow-hidden group ${
                  location.pathname === link.path 
                    ? "text-white" 
                    : "text-[#0A1F44] hover:text-white"
                }`}
                style={{ minWidth: 120 }}
                onClick={closeDropdown}
              >
                {/* Active/hover background */}
                <div className={`absolute inset-0 bg-gradient-to-r from-[#008080] to-[#20B2AA] transition-all duration-300 ${
                  location.pathname === link.path 
                    ? "opacity-100 scale-100" 
                    : "opacity-0 scale-95 group-hover:opacity-100 group-hover:scale-100"
                }`} style={{ borderRadius: '12px' }}></div>
                
                {/* Subtle glow effect */}
                <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-10 transition-opacity duration-300" style={{ borderRadius: '12px' }}></div>
                
                <span className="relative z-10 truncate">{link.name}</span>
              </Link>
            )}
            
            {/* Modern Dropdown Menu */}
            {link.hasDropdown && hoveredDropdown === link.name && (
              <div className={`absolute top-full left-0 mt-3 w-72 bg-white backdrop-blur-lg bg-opacity-95 border border-gray-100 rounded-2xl shadow-2xl z-50 overflow-hidden ${
                link.isScrollable ? 'max-h-96 overflow-y-auto' : ''
              }`}>
                {/* Modern gradient header */}
                <div className="bg-gradient-to-r from-[#008080] to-[#20B2AA] p-3">
                  <h3 className="text-white font-semibold text-sm">{link.name}</h3>
                </div>
                
                <div className="py-2">
                  {link.dropdownItems.map((item, index) => (
                    <Link
                      key={item.name}
                      to={item.path}
                      className="block px-4 py-3 text-sm text-[#0A1F44] hover:bg-gradient-to-r hover:from-[#008080] hover:to-[#20B2AA] hover:text-white transition-all duration-200 border-b border-gray-50 last:border-b-0 group"
                      onClick={closeDropdown}
                    >
                      <span className="flex items-center">
                        <span className="w-1.5 h-1.5 bg-[#008080] rounded-full mr-3 group-hover:bg-white transition-colors duration-200"></span>
                        {item.name}
                      </span>
                    </Link>
                  ))}
                </div>
              </div>
            )}
          </div>
        ))}
      </nav>

      {/* Mobile Navigation */}
      <div className={`lg:hidden w-full overflow-hidden transition-all duration-300 ${isMobileMenuOpen ? 'max-h-screen' : 'max-h-0'}`}>
        <nav className="px-4 py-6 bg-gradient-to-br from-gray-50 to-gray-100">
          <div className="space-y-3">
            {navLinks.map((link) => (
              <div key={link.name}>
                {link.hasDropdown ? (
                  <div>
                    {/* If dropdown has main path (like Home), show the main link first */}
                    {link.path && (
                      <Link
                        to={link.path}
                        className={`block px-5 py-4 rounded-2xl font-semibold transition-all duration-300 shadow-sm mb-2 ${
                          location.pathname === link.path 
                            ? "bg-gradient-to-r from-[#008080] to-[#20B2AA] text-white shadow-lg" 
                            : "bg-white text-[#0A1F44] hover:bg-gradient-to-r hover:from-[#008080] hover:to-[#20B2AA] hover:text-white hover:shadow-lg"
                        }`}
                        onClick={() => setIsMobileMenuOpen(false)}
                      >
                        <span className="flex items-center">
                          <span className={`w-2 h-2 rounded-full mr-3 transition-colors duration-300 ${
                            location.pathname === link.path ? 'bg-white' : 'bg-[#008080]'
                          }`}></span>
                          {link.name}
                        </span>
                      </Link>
                    )}
                    
                    {/* Dropdown toggle button */}
                    <button
                      className={`w-full flex items-center justify-between px-5 py-4 rounded-2xl font-semibold transition-all duration-300 shadow-sm ${
                        hoveredDropdown === link.name 
                          ? "bg-gradient-to-r from-[#008080] to-[#20B2AA] text-white shadow-lg"
                          : "bg-white text-[#0A1F44] hover:bg-gradient-to-r hover:from-[#008080] hover:to-[#20B2AA] hover:text-white hover:shadow-lg"
                      }`}
                      onClick={() => toggleDropdown(link.name)}
                    >
                      <span className="flex items-center">
                        <span className={`w-2 h-2 rounded-full mr-3 transition-colors duration-300 ${
                          hoveredDropdown === link.name ? 'bg-white' : 'bg-[#008080]'
                        }`}></span>
                        {link.path ? `More ${link.name}` : link.name}
                      </span>
                      <svg 
                        className={`w-5 h-5 transition-all duration-300 ${
                          hoveredDropdown === link.name ? 'rotate-180 text-white' : 'text-[#008080]'
                        }`} 
                        fill="none" 
                        stroke="currentColor" 
                        viewBox="0 0 24 24"
                      >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7" />
                      </svg>
                    </button>
                    {hoveredDropdown === link.name && (
                      <div className="mt-3 ml-6 space-y-2 animate-in slide-in-from-top-2 duration-300">
                        {link.dropdownItems.map((item) => (
                          <Link
                            key={item.name}
                            to={item.path}
                            className="block px-4 py-3 text-sm text-[#0A1F44] bg-white rounded-xl hover:bg-gradient-to-r hover:from-[#008080] hover:to-[#20B2AA] hover:text-white transition-all duration-200 shadow-sm hover:shadow-md"
                            onClick={() => {
                              closeDropdown();
                              setIsMobileMenuOpen(false);
                            }}
                          >
                            <span className="flex items-center">
                              <span className="w-1.5 h-1.5 bg-[#008080] rounded-full mr-3"></span>
                              {item.name}
                            </span>
                          </Link>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <Link
                    to={link.path}
                    className={`block px-5 py-4 rounded-2xl font-semibold transition-all duration-300 shadow-sm ${
                      location.pathname === link.path 
                        ? "bg-gradient-to-r from-[#008080] to-[#20B2AA] text-white shadow-lg" 
                        : "bg-white text-[#0A1F44] hover:bg-gradient-to-r hover:from-[#008080] hover:to-[#20B2AA] hover:text-white hover:shadow-lg"
                    }`}
                    onClick={() => setIsMobileMenuOpen(false)}
                  >
                    <span className="flex items-center">
                      <span className={`w-2 h-2 rounded-full mr-3 transition-colors duration-300 ${
                        location.pathname === link.path ? 'bg-white' : 'bg-[#008080]'
                      }`}></span>
                      {link.name}
                    </span>
                  </Link>
                )}
              </div>
            ))}
            
            {/* Modern Mobile Phone Number */}
            <div className="pt-6 border-t border-gray-200">
              <div className="flex items-center px-5 py-4 bg-gradient-to-r from-[#008080] to-[#20B2AA] rounded-2xl shadow-lg">
                <svg className="w-6 h-6 text-white mr-3" viewBox="0 0 15 15" fill="none" xmlns="http://www.w3.org/2000/svg">
                  <path d="M4.71922 0.5H2.5C1.39543 0.5 0.5 1.39543 0.5 2.5V4.5C0.5 10.0228 4.97715 14.5 10.5 14.5H12.5C13.6046 14.5 14.5 13.6046 14.5 12.5V11.118C14.5 10.7393 14.286 10.393 13.9472 10.2236L11.5313 9.01564C10.987 8.74349 10.3278 9.01652 10.1354 9.59384L9.83762 10.4871C9.64474 11.0658 9.05118 11.4102 8.45309 11.2906C6.05929 10.8119 4.18814 8.94071 3.70938 6.54691C3.58976 5.94882 3.93422 5.35526 4.51286 5.16238L5.62149 4.79284C6.11721 4.6276 6.40214 4.10855 6.2754 3.60162L5.68937 1.25746C5.57807 0.812297 5.17809 0.5 4.71922 0.5Z" stroke="currentColor"/>
                </svg>
                <div>
                  <span className="text-white font-bold text-sm">+91-7889093147</span>
                  <p className="text-white text-xs opacity-90">Call us anytime!</p>
                </div>
              </div>
            </div>
          </div>
        </nav>
      </div>
    </header>
  );
};

export default Header;
