import React, { useState, useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import Header from '../components/Header';
import Footer from '../components/Footer';
import CounterAnimation from '../components/CounterAnimation';

const GeneralDentistryCourse = () => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    country: '',
    education: '',
    experience: '',
    courseType: 'clinical'
  });

  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-out-cubic',
      offset: 50,
      once: true
    });
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    alert('Thank you for your enrollment! We will contact you shortly.');
  };

  const courseModules = [
    {
      module: "Module 1: Dental Foundations",
      topics: ["Oral Anatomy", "Dental Materials", "Infection Control", "Patient Assessment"]
    },
    {
      module: "Module 2: Preventive Dentistry",
      topics: ["Oral Hygiene", "Fluoride Therapy", "Sealants", "Risk Assessment"]
    },
    {
      module: "Module 3: Restorative Procedures",
      topics: ["Cavity Preparation", "Composite Fillings", "Crown & Bridge", "Basic Endodontics"]
    },
    {
      module: "Module 4: Periodontal Care",
      topics: ["Gum Disease Treatment", "Scaling & Root Planing", "Maintenance Protocols", "Surgical Basics"]
    },
    {
      module: "Module 5: Oral Surgery",
      topics: ["Simple Extractions", "Surgical Techniques", "Pain Management", "Post-operative Care"]
    },
    {
      module: "Module 6: Practice Management",
      topics: ["Patient Communication", "Treatment Planning", "Practice Efficiency", "Quality Assurance"]
    }
  ];

  const courseFeatures = [
    {
      icon: "🦷",
      title: "Comprehensive Training",
      description: "Complete general dentistry education covering all aspects"
    },
    {
      icon: "🎥",
      title: "Clinical Procedures",
      description: "150+ hours of general dental procedures"
    },
    {
      icon: "🔬",
      title: "Evidence-Based Practice",
      description: "Latest research and clinical guidelines"
    },
    {
      icon: "👨‍⚕️",
      title: "Expert Faculty",
      description: "Learn from experienced general dentists"
    },
    {
      icon: "💻",
      title: "Digital Integration",
      description: "Modern technology in general practice"
    },
    {
      icon: "🏆",
      title: "Professional Certification",
      description: "General dentistry practice certification"
    }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />
      
      {/* Hero Section with Digital Grid Matrix Design */}
      <section className="relative min-h-screen bg-gradient-to-br from-gray-900 via-blue-900 to-indigo-900 text-white overflow-hidden">
        {/* Digital Grid Background */}
        <div className="absolute inset-0">
          <div className="absolute inset-0" style={{
            backgroundImage: `
              linear-gradient(rgba(59,130,246,0.1) 1px, transparent 1px),
              linear-gradient(90deg, rgba(59,130,246,0.1) 1px, transparent 1px),
              linear-gradient(rgba(59,130,246,0.05) 1px, transparent 1px),
              linear-gradient(90deg, rgba(59,130,246,0.05) 1px, transparent 1px)
            `,
            backgroundSize: '100px 100px, 100px 100px, 20px 20px, 20px 20px',
            animation: 'grid-move 20s linear infinite'
          }}></div>
        </div>

        {/* Matrix Glow Effects */}
        <div className="absolute inset-0">
          <div className="absolute top-1/4 left-1/4 w-64 h-64 bg-blue-500/20 rounded-full blur-3xl animate-pulse"></div>
          <div className="absolute bottom-1/4 right-1/4 w-72 h-72 bg-cyan-500/15 rounded-full blur-3xl animate-pulse" style={{animationDelay: '1s'}}></div>
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-80 h-80 bg-indigo-500/10 rounded-full blur-3xl animate-pulse" style={{animationDelay: '2s'}}></div>
        </div>

        {/* Digital Elements */}
        <div className="absolute inset-0 opacity-20">
          <div className="absolute top-20 left-20 w-8 h-8 border-2 border-blue-400 transform rotate-45 animate-spin-slow"></div>
          <div className="absolute top-1/3 right-1/4 w-6 h-6 border-2 border-cyan-400 animate-pulse"></div>
          <div className="absolute bottom-1/3 left-1/3 w-10 h-10 border-2 border-indigo-400 transform rotate-45 animate-spin-slow" style={{animationDelay: '1s'}}></div>
          <div className="absolute bottom-20 right-20 w-12 h-12 border-2 border-blue-300 animate-pulse" style={{animationDelay: '0.5s'}}></div>
        </div>

        {/* Data Stream Lines */}
        <div className="absolute inset-0 opacity-30">
          <svg className="w-full h-full" viewBox="0 0 1200 800">
            <defs>
              <linearGradient id="dataStream" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="transparent" />
                <stop offset="50%" stopColor="#3b82f6" stopOpacity="0.8" />
                <stop offset="100%" stopColor="transparent" />
              </linearGradient>
            </defs>
            <line x1="0" y1="100" x2="1200" y2="150" stroke="url(#dataStream)" strokeWidth="2">
              <animate attributeName="x1" values="0;1200;0" dur="8s" repeatCount="indefinite" />
              <animate attributeName="x2" values="1200;2400;1200" dur="8s" repeatCount="indefinite" />
            </line>
            <line x1="0" y1="300" x2="1200" y2="280" stroke="url(#dataStream)" strokeWidth="2">
              <animate attributeName="x1" values="0;1200;0" dur="10s" repeatCount="indefinite" />
              <animate attributeName="x2" values="1200;2400;1200" dur="10s" repeatCount="indefinite" />
            </line>
            <line x1="0" y1="500" x2="1200" y2="520" stroke="url(#dataStream)" strokeWidth="2">
              <animate attributeName="x1" values="0;1200;0" dur="12s" repeatCount="indefinite" />
              <animate attributeName="x2" values="1200;2400;1200" dur="12s" repeatCount="indefinite" />
            </line>
          </svg>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-32 pb-20">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            {/* Content Side */}
            <div data-aos="fade-right">
              <div className="inline-flex items-center px-6 py-3 rounded-lg bg-blue-500/10 backdrop-blur-sm border border-blue-500/30 mb-8">
                <div className="w-3 h-3 bg-blue-400 rounded-sm mr-3 animate-pulse"></div>
                <span className="text-sm font-medium font-mono">COMPREHENSIVE_DENTISTRY.EXE</span>
              </div>
              
              <h1 className="text-5xl md:text-7xl font-bold mb-8 leading-tight">
                <span className="block text-white font-mono">General</span>
                <span className="block bg-gradient-to-r from-blue-400 via-cyan-400 to-indigo-400 bg-clip-text text-transparent font-mono">
                  Dentistry
                </span>
                <span className="block text-white font-mono">System</span>
              </h1>
              
              <p className="text-xl md:text-2xl mb-10 text-gray-300 leading-relaxed">
                Execute comprehensive dental care protocols with systematic precision. Master all essential procedures through structured digital learning modules.
              </p>

              {/* Digital Stats Grid */}
              <div className="grid grid-cols-2 gap-6 mb-10">
                <div className="bg-blue-500/10 backdrop-blur-xl rounded-lg p-6 border border-blue-500/30 hover:bg-blue-500/20 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-blue-400 mb-2 font-mono">
                    <CounterAnimation end={500} duration={2000} />+
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors text-sm">PROCEDURES_MASTERED</p>
                </div>
                <div className="bg-cyan-500/10 backdrop-blur-xl rounded-lg p-6 border border-cyan-500/30 hover:bg-cyan-500/20 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-cyan-400 mb-2 font-mono">
                    <CounterAnimation end={24} duration={1500} />
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors text-sm">WEEKS_TRAINING</p>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4">
                <button className="px-8 py-4 bg-gradient-to-r from-blue-500 to-cyan-600 rounded-lg font-semibold text-white hover:from-blue-600 hover:to-cyan-700 transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-blue-500/25 font-mono">
                  INITIALIZE_TRAINING
                </button>
                <button className="px-8 py-4 bg-blue-500/10 backdrop-blur-xl rounded-lg font-semibold text-white border border-blue-500/30 hover:bg-blue-500/20 transition-all duration-300 font-mono">
                  ACCESS_MODULES
                </button>
              </div>
            </div>

            {/* Visual Side - Digital Grid Matrix */}
            <div className="relative" data-aos="fade-left">
              <div className="relative w-full h-96 lg:h-[500px]">
                {/* Main Digital Display */}
                <div className="absolute inset-0 bg-blue-500/10 backdrop-blur-xl rounded-lg border border-blue-500/30 shadow-2xl">
                  <div className="absolute inset-2 border border-blue-400/30 rounded">
                    <div className="p-8 h-full flex flex-col">
                      {/* Digital Header */}
                      <div className="border-b border-blue-400/30 pb-4 mb-6">
                        <h3 className="text-blue-400 font-mono text-lg">DENTAL_SYSTEM_V2.0</h3>
                        <div className="flex items-center mt-2">
                          <div className="w-2 h-2 bg-green-400 rounded-full mr-2 animate-pulse"></div>
                          <span className="text-green-400 text-sm font-mono">ONLINE</span>
                        </div>
                      </div>

                      {/* Digital Content */}
                      <div className="flex-1 flex flex-col justify-center items-center text-center">
                        <div className="w-20 h-20 border-2 border-cyan-400 rounded-lg mb-6 flex items-center justify-center relative">
                          <svg className="w-10 h-10 text-cyan-400" fill="currentColor" viewBox="0 0 20 20">
                            <path fillRule="evenodd" d="M3 4a1 1 0 011-1h12a1 1 0 011 1v2a1 1 0 01-1 1H4a1 1 0 01-1-1V4zm0 4a1 1 0 011-1h6a1 1 0 011 1v6a1 1 0 01-1 1H4a1 1 0 01-1-1V8zm8 0a1 1 0 011-1h4a1 1 0 011 1v2a1 1 0 01-1 1h-4a1 1 0 01-1-1V8z" clipRule="evenodd" />
                          </svg>
                          <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-400 rounded-full animate-ping"></div>
                        </div>
                        <h3 className="text-xl font-bold text-white mb-4 font-mono">SYSTEM_PROTOCOLS</h3>
                        <p className="text-gray-300 font-mono text-sm">Comprehensive dental care algorithms and procedures</p>
                      </div>

                      {/* Digital Footer */}
                      <div className="border-t border-blue-400/30 pt-4">
                        <div className="flex justify-between text-xs font-mono text-gray-400">
                          <span>STATUS: ACTIVE</span>
                          <span>MODULES: 24</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Floating Digital Elements */}
                <div className="absolute -top-4 -left-4 w-8 h-8 border-2 border-blue-400 animate-spin-slow"></div>
                <div className="absolute -bottom-4 -right-4 w-10 h-10 border-2 border-cyan-400 animate-pulse"></div>
                <div className="absolute top-1/4 -right-6 w-6 h-6 border-2 border-indigo-400 transform rotate-45 animate-spin-slow"></div>
                <div className="absolute bottom-1/3 -left-6 w-12 h-12 border-2 border-blue-300 animate-pulse" style={{animationDelay: '1s'}}></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Course Features */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Features
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive training in general dentistry
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseFeatures.map((feature, index) => (
              <div 
                key={index} 
                className="bg-gray-50 rounded-lg p-6 text-center hover:shadow-lg transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <div className="text-4xl mb-4">{feature.icon}</div>
                <h3 className="text-xl font-semibold text-gray-900 mb-3">{feature.title}</h3>
                <p className="text-gray-600">{feature.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Course Modules */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Curriculum
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive modules covering all aspects of general dentistry
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseModules.map((module, index) => (
              <div 
                key={index} 
                className="bg-white rounded-lg p-6 shadow-lg hover:shadow-xl transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <h3 className="text-xl font-semibold text-indigo-800 mb-4">{module.module}</h3>
                <ul className="space-y-2">
                  {module.topics.map((topic, topicIndex) => (
                    <li key={topicIndex} className="flex items-start">
                      <span className="text-indigo-600 mr-2">•</span>
                      <span className="text-gray-700">{topic}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>



      {/* Enrollment Form */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Enroll Now
            </h2>
            <p className="text-xl text-gray-600">
              Start your journey in general dentistry today
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-lg p-8" data-aos="fade-up">
            <form onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    First Name
                  </label>
                  <input
                    type="text"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Last Name
                  </label>
                  <input
                    type="text"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    required
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Phone
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                    required
                  />
                </div>
              </div>
              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Country
                </label>
                <input
                  type="text"
                  name="country"
                  value={formData.country}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
                  required
                />
              </div>
              <div className="text-center">
                <button
                  type="submit"
                  className="bg-indigo-600 text-white py-3 px-8 rounded-lg font-semibold hover:bg-indigo-700 transition duration-200"
                >
                  Enroll Now
                </button>
                <p className="text-sm text-gray-600 mt-4">
                  For course details and pricing, call us at +91 7889093147
                </p>
              </div>
            </form>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default GeneralDentistryCourse;
