import React, { useState, useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import Header from '../components/Header';
import Footer from '../components/Footer';

const TreatmentPlanningCourse = () => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    country: '',
    education: '',
    experience: '',
    paymentMethod: 'card'
  });

  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-out-cubic',
      offset: 50,
      once: true
    });
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    alert('Thank you for your enrollment! We will contact you shortly.');
  };

  const courseModules = [
    {
      module: "Module 1: Assessment Fundamentals",
      topics: ["Comprehensive Examination", "Medical History Analysis", "Risk Assessment", "Diagnostic Tools"]
    },
    {
      module: "Module 2: Treatment Options",
      topics: ["Treatment Alternatives", "Evidence-Based Planning", "Cost-Benefit Analysis", "Patient Preferences"]
    },
    {
      module: "Module 3: Multidisciplinary Planning",
      topics: ["Collaborative Approach", "Specialist Referrals", "Team Communication", "Integrated Care"]
    },
    {
      module: "Module 4: Digital Planning Tools",
      topics: ["Software Applications", "3D Imaging", "Virtual Planning", "Digital Workflows"]
    },
    {
      module: "Module 5: Case Presentation",
      topics: ["Patient Communication", "Treatment Proposals", "Informed Consent", "Case Acceptance"]
    },
    {
      module: "Module 6: Implementation & Follow-up",
      topics: ["Treatment Sequencing", "Progress Monitoring", "Outcome Assessment", "Long-term Maintenance"]
    }
  ];

  const courseFeatures = [
    {
      icon: "📋",
      title: "Comprehensive Planning",
      description: "Master systematic treatment planning approaches"
    },
    {
      icon: "🔍",
      title: "Case Analysis",
      description: "Advanced diagnostic and assessment skills"
    },
    {
      icon: "👥",
      title: "Multidisciplinary Approach",
      description: "Collaborative treatment planning strategies"
    },
    {
      icon: "💻",
      title: "Digital Tools",
      description: "Modern planning software and technologies"
    },
    {
      icon: "🗣️",
      title: "Communication Skills",
      description: "Effective patient consultation techniques"
    },
    {
      icon: "🎯",
      title: "Strategic Thinking",
      description: "Develop logical treatment sequencing"
    }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />
      
      {/* Hero Section */}
      <section className="bg-gradient-to-br from-[#0A1F44] to-[#008080] text-white py-20">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8" data-aos="fade-up">
          <div className="text-center">
            <h1 className="text-4xl md:text-6xl font-bold mb-6">
              Treatment Planning Course
            </h1>
            <p className="text-xl md:text-2xl mb-8 max-w-3xl mx-auto">
              Master comprehensive treatment planning for complex dental cases with multidisciplinary approaches.
            </p>
            <div className="flex flex-col sm:flex-row justify-center items-center space-y-4 sm:space-y-0 sm:space-x-8">
              <div className="bg-white bg-opacity-20 rounded-lg p-4">
                <span className="text-lg font-semibold">Duration: 4 Months</span>
              </div>
              <div className="bg-white bg-opacity-20 rounded-lg p-4">
                <span className="text-lg font-semibold">Level: Advanced</span>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Course Features */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Features
            </h2>
            <p className="text-xl text-gray-600">
              Strategic treatment planning expertise
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseFeatures.map((feature, index) => (
              <div 
                key={index} 
                className="bg-gray-50 rounded-lg p-6 text-center hover:shadow-lg transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <div className="text-4xl mb-4">{feature.icon}</div>
                <h3 className="text-xl font-semibold text-gray-900 mb-3">{feature.title}</h3>
                <p className="text-gray-600">{feature.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Course Modules */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Curriculum
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive treatment planning methodology
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseModules.map((module, index) => (
              <div 
                key={index} 
                className="bg-white rounded-lg p-6 shadow-lg hover:shadow-xl transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <h3 className="text-xl font-semibold text-[#0A1F44] mb-4">{module.module}</h3>
                <ul className="space-y-2">
                  {module.topics.map((topic, topicIndex) => (
                    <li key={topicIndex} className="flex items-start">
                      <span className="text-[#008080] mr-2">•</span>
                      <span className="text-gray-700">{topic}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>



      {/* Enrollment Form */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Enroll Now
            </h2>
            <p className="text-xl text-gray-600">
              Master strategic treatment planning
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-lg p-8" data-aos="fade-up">
            <form onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-[#0A1F44] mb-2">
                    First Name
                  </label>
                  <input
                    type="text"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-[#008080] focus:border-[#008080]"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#0A1F44] mb-2">
                    Last Name
                  </label>
                  <input
                    type="text"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-[#008080] focus:border-[#008080]"
                    required
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-[#0A1F44] mb-2">
                    Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-[#008080] focus:border-[#008080]"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#0A1F44] mb-2">
                    Phone
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-[#008080] focus:border-[#008080]"
                    required
                  />
                </div>
              </div>
              <div className="mb-6">
                <label className="block text-sm font-medium text-[#0A1F44] mb-2">
                  Country
                </label>
                <input
                  type="text"
                  name="country"
                  value={formData.country}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-[#008080] focus:border-[#008080]"
                  required
                />
              </div>
              <div className="text-center">
                <button
                  type="submit"
                  className="bg-[#008080] text-white py-3 px-8 rounded-lg font-semibold hover:bg-[#006666] transition duration-200"
                >
                  Enroll Now
                </button>
                <p className="text-sm text-gray-600 mt-2">
                  For course details and pricing, call us at +91 7889093147
                </p>
              </div>
            </form>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default TreatmentPlanningCourse;
