import React, { useState, useEffect } from 'react';
import AOS from 'aos';
import 'aos/dist/aos.css';
import Header from '../components/Header';
import Footer from '../components/Footer';
import CounterAnimation from '../components/CounterAnimation';

const LaserDentistryCourse = () => {
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    country: '',
    education: '',
    experience: '',
    paymentMethod: 'card'
  });

  useEffect(() => {
    AOS.init({
      duration: 800,
      easing: 'ease-out-cubic',
      offset: 50,
      once: true
    });
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Form submitted:', formData);
    alert('Thank you for your enrollment! We will contact you shortly.');
  };

  const courseModules = [
    {
      module: "Module 1: Laser Physics & Safety",
      topics: ["Laser Fundamentals", "Light-Tissue Interaction", "Safety Protocols", "Regulatory Standards"]
    },
    {
      module: "Module 2: Soft Tissue Applications",
      topics: ["Gingival Surgery", "Lesion Removal", "Frenectomy", "Periodontal Therapy"]
    },
    {
      module: "Module 3: Hard Tissue Applications",
      topics: ["Cavity Preparation", "Caries Removal", "Dentin Hypersensitivity", "Endodontic Applications"]
    },
    {
      module: "Module 4: Surgical Procedures",
      topics: ["Oral Surgery", "Implant Site Preparation", "Bone Surgery", "Hemostasis"]
    },
    {
      module: "Module 5: Cosmetic Applications",
      topics: ["Teeth Whitening", "Gum Contouring", "Crown Lengthening", "Aesthetic Procedures"]
    },
    {
      module: "Module 6: Clinical Integration",
      topics: ["Patient Selection", "Treatment Planning", "Practice Integration", "Maintenance Protocols"]
    }
  ];

  const courseFeatures = [
    {
      icon: "⚡",
      title: "Advanced Laser Technology",
      description: "Comprehensive training in modern laser dentistry"
    },
    {
      icon: "🎥",
      title: "Live Demonstrations",
      description: "110+ hours of laser procedures and techniques"
    },
    {
      icon: "🔬",
      title: "Scientific Foundation",
      description: "Evidence-based laser applications"
    },
    {
      icon: "👨‍⚕️",
      title: "Expert Instructors",
      description: "Learn from certified laser specialists"
    },
    {
      icon: "💻",
      title: "Modern Equipment",
      description: "Training on latest laser systems"
    },
    {
      icon: "🏆",
      title: "Laser Certification",
      description: "Professional laser dentistry certification"
    }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      <Header />
      
      {/* Hero Section with Laser Beam Precision Design */}
      <section className="relative min-h-screen bg-gradient-to-br from-red-900 via-orange-900 to-yellow-900 text-white overflow-hidden">
        {/* Laser Beam Background */}
        <div className="absolute inset-0">
          <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-red-500/10 via-orange-500/15 to-yellow-500/10"></div>
          <div className="absolute top-1/4 left-1/4 w-96 h-2 bg-gradient-to-r from-transparent via-red-400/60 to-transparent blur-sm animate-pulse"></div>
          <div className="absolute bottom-1/3 right-1/4 w-80 h-1 bg-gradient-to-r from-transparent via-orange-400/70 to-transparent blur-sm animate-pulse" style={{animationDelay: '1s'}}></div>
          <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-72 h-1 bg-gradient-to-r from-transparent via-yellow-400/50 to-transparent blur-sm animate-pulse" style={{animationDelay: '2s'}}></div>
        </div>

        {/* Laser Grid Pattern */}
        <div className="absolute inset-0 opacity-20">
          <svg className="w-full h-full" viewBox="0 0 1200 800">
            <defs>
              <pattern id="laser-grid" x="0" y="0" width="60" height="60" patternUnits="userSpaceOnUse">
                <circle cx="30" cy="30" r="1" fill="#ef4444" opacity="0.6">
                  <animate attributeName="opacity" values="0.6;1;0.6" dur="2s" repeatCount="indefinite" />
                </circle>
              </pattern>
              <radialGradient id="laser-glow" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor="#dc2626" stopOpacity="0.8" />
                <stop offset="50%" stopColor="#ea580c" stopOpacity="0.4" />
                <stop offset="100%" stopColor="#ca8a04" stopOpacity="0.2" />
              </radialGradient>
            </defs>
            <rect width="100%" height="100%" fill="url(#laser-grid)" />
            <circle cx="600" cy="400" r="200" fill="url(#laser-glow)" opacity="0.3">
              <animate attributeName="r" values="200;250;200" dur="4s" repeatCount="indefinite" />
            </circle>
          </svg>
        </div>

        {/* Laser Beam Effects */}
        <div className="absolute inset-0">
          <div className="absolute top-20 left-20 w-1 h-32 bg-gradient-to-b from-red-400 to-transparent animate-pulse"></div>
          <div className="absolute top-1/3 right-1/4 w-1 h-24 bg-gradient-to-b from-orange-400 to-transparent animate-pulse" style={{animationDelay: '1s'}}></div>
          <div className="absolute bottom-1/3 left-1/3 w-1 h-40 bg-gradient-to-b from-yellow-400 to-transparent animate-pulse" style={{animationDelay: '2s'}}></div>
          <div className="absolute bottom-20 right-20 w-1 h-28 bg-gradient-to-b from-red-400 to-transparent animate-pulse" style={{animationDelay: '0.5s'}}></div>
        </div>

        {/* Precision Targeting Lines */}
        <div className="absolute inset-0 opacity-40">
          <svg className="w-full h-full" viewBox="0 0 1200 800">
            <line x1="0" y1="400" x2="1200" y2="400" stroke="#ef4444" strokeWidth="1" strokeDasharray="5,5">
              <animate attributeName="stroke-opacity" values="0.4;1;0.4" dur="3s" repeatCount="indefinite" />
            </line>
            <line x1="600" y1="0" x2="600" y2="800" stroke="#ea580c" strokeWidth="1" strokeDasharray="5,5">
              <animate attributeName="stroke-opacity" values="0.4;1;0.4" dur="3s" repeatCount="indefinite" begin="1s" />
            </line>
          </svg>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-32 pb-20">
          <div className="grid lg:grid-cols-2 gap-12 items-center">
            {/* Content Side */}
            <div data-aos="fade-right">
              <div className="inline-flex items-center px-6 py-3 rounded-full bg-red-500/20 backdrop-blur-sm border border-red-500/30 mb-8">
                <div className="w-3 h-3 bg-red-400 rounded-full mr-3 animate-pulse"></div>
                <span className="text-sm font-medium">Precision Laser Technology</span>
              </div>
              
              <h1 className="text-5xl md:text-7xl font-bold mb-8 leading-tight">
                <span className="block bg-gradient-to-r from-red-400 via-orange-400 to-yellow-400 bg-clip-text text-transparent">
                  Laser
                </span>
                <span className="block text-white">Dentistry</span>
                <span className="block bg-gradient-to-r from-yellow-400 via-orange-400 to-red-400 bg-clip-text text-transparent">
                  Precision
                </span>
              </h1>
              
              <p className="text-xl md:text-2xl mb-10 text-gray-300 leading-relaxed">
                Master cutting-edge laser technology for minimally invasive dental procedures. Achieve unparalleled precision in soft and hard tissue treatments.
              </p>

              {/* Laser Precision Stats */}
              <div className="grid grid-cols-2 gap-6 mb-10">
                <div className="bg-red-500/10 backdrop-blur-xl rounded-2xl p-6 border border-red-500/30 hover:bg-red-500/20 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-red-400 mb-2">
                    <CounterAnimation end={99} duration={2000} />.9%
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors">Precision Rate</p>
                </div>
                <div className="bg-orange-500/10 backdrop-blur-xl rounded-2xl p-6 border border-orange-500/30 hover:bg-orange-500/20 transition-all duration-300 group">
                  <div className="text-4xl font-bold text-orange-400 mb-2">
                    <CounterAnimation end={16} duration={1500} />
                  </div>
                  <p className="text-gray-300 group-hover:text-white transition-colors">Weeks Training</p>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-4">
                <button className="px-8 py-4 bg-gradient-to-r from-red-500 to-orange-600 rounded-xl font-semibold text-white hover:from-red-600 hover:to-orange-700 transition-all duration-300 transform hover:scale-105 shadow-lg hover:shadow-red-500/25">
                  Begin Laser Training
                </button>
                <button className="px-8 py-4 bg-red-500/10 backdrop-blur-xl rounded-xl font-semibold text-white border border-red-500/30 hover:bg-red-500/20 transition-all duration-300">
                  Technology Overview
                </button>
              </div>
            </div>

            {/* Visual Side - Laser Beam Precision */}
            <div className="relative" data-aos="fade-left">
              <div className="relative w-full h-96 lg:h-[500px]">
                {/* Main Laser Display */}
                <div className="absolute inset-0 bg-gradient-to-br from-red-500/20 to-orange-500/10 backdrop-blur-xl rounded-3xl border border-red-500/30 shadow-2xl">
                  <div className="absolute inset-4 bg-gradient-to-br from-red-500/10 to-transparent rounded-2xl border border-red-500/20">
                    <div className="p-8 h-full flex flex-col justify-center items-center text-center relative">
                      {/* Crosshair Target */}
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-32 h-32 border-2 border-red-400/50 rounded-full">
                          <div className="w-full h-full border-2 border-orange-400/30 rounded-full animate-ping"></div>
                        </div>
                        <div className="absolute w-40 h-1 bg-red-400/60"></div>
                        <div className="absolute w-1 h-40 bg-red-400/60"></div>
                      </div>

                      <div className="relative z-10">
                        <div className="w-24 h-24 bg-gradient-to-br from-red-400 via-orange-500 to-yellow-500 rounded-full mb-6 flex items-center justify-center shadow-lg animate-pulse">
                          <svg className="w-12 h-12 text-white" fill="currentColor" viewBox="0 0 20 20">
                            <path fillRule="evenodd" d="M11.3 1.046A1 1 0 0112 2v5h4a1 1 0 01.82 1.573l-7 10A1 1 0 018 18v-5H4a1 1 0 01-.82-1.573l7-10a1 1 0 011.12-.38z" clipRule="evenodd" />
                          </svg>
                        </div>
                        <h3 className="text-2xl font-bold text-white mb-4">Laser Precision</h3>
                        <p className="text-gray-300">Advanced laser technology for precise dental treatments</p>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Floating Laser Elements */}
                <div className="absolute -top-6 -left-6 w-20 h-20 bg-gradient-to-br from-red-500/70 to-orange-500/70 backdrop-blur-xl rounded-full border border-red-500/30 animate-float">
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="w-2 h-2 bg-red-300 rounded-full animate-ping"></div>
                  </div>
                </div>
                <div className="absolute -bottom-6 -right-6 w-24 h-24 bg-gradient-to-br from-orange-500/70 to-yellow-500/70 backdrop-blur-xl rounded-full border border-orange-500/30 animate-float" style={{animationDelay: '1s'}}>
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="w-3 h-3 bg-orange-300 rounded-full animate-ping"></div>
                  </div>
                </div>
                <div className="absolute top-1/4 -right-10 w-14 h-14 bg-gradient-to-br from-yellow-500/70 to-red-500/70 backdrop-blur-xl rounded-full border border-yellow-500/30 animate-float" style={{animationDelay: '2s'}}>
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="w-1 h-1 bg-yellow-300 rounded-full animate-ping"></div>
                  </div>
                </div>
                <div className="absolute bottom-1/3 -left-8 w-16 h-16 bg-gradient-to-br from-red-500/70 to-orange-500/70 backdrop-blur-xl rounded-full border border-red-500/30 animate-float" style={{animationDelay: '0.5s'}}>
                  <div className="w-full h-full flex items-center justify-center">
                    <div className="w-2 h-2 bg-red-300 rounded-full animate-ping"></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Course Features */}
      <section className="py-16 bg-white">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Features
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive training in laser dentistry
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseFeatures.map((feature, index) => (
              <div 
                key={index} 
                className="bg-gray-50 rounded-lg p-6 text-center hover:shadow-lg transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <div className="text-4xl mb-4">{feature.icon}</div>
                <h3 className="text-xl font-semibold text-gray-900 mb-3">{feature.title}</h3>
                <p className="text-gray-600">{feature.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Course Modules */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Course Curriculum
            </h2>
            <p className="text-xl text-gray-600">
              Comprehensive modules covering all aspects of laser dentistry
            </p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {courseModules.map((module, index) => (
              <div 
                key={index} 
                className="bg-white rounded-lg p-6 shadow-lg hover:shadow-xl transition duration-300"
                data-aos="fade-up"
                data-aos-delay={index * 100}
              >
                <h3 className="text-xl font-semibold text-red-800 mb-4">{module.module}</h3>
                <ul className="space-y-2">
                  {module.topics.map((topic, topicIndex) => (
                    <li key={topicIndex} className="flex items-start">
                      <span className="text-red-600 mr-2">•</span>
                      <span className="text-gray-700">{topic}</span>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>
      </section>



      {/* Enrollment Form */}
      <section className="py-16 bg-gray-50">
        <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="text-center mb-12" data-aos="fade-up">
            <h2 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
              Enroll Now
            </h2>
            <p className="text-xl text-gray-600">
              Start your journey in laser dentistry today
            </p>
          </div>

          <div className="bg-white rounded-lg shadow-lg p-8" data-aos="fade-up">
            <form onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    First Name
                  </label>
                  <input
                    type="text"
                    name="firstName"
                    value={formData.firstName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-red-500 focus:border-red-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Last Name
                  </label>
                  <input
                    type="text"
                    name="lastName"
                    value={formData.lastName}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-red-500 focus:border-red-500"
                    required
                  />
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Email
                  </label>
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-red-500 focus:border-red-500"
                    required
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Phone
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-red-500 focus:border-red-500"
                    required
                  />
                </div>
              </div>
              <div className="mb-6">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Country
                </label>
                <input
                  type="text"
                  name="country"
                  value={formData.country}
                  onChange={handleInputChange}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-red-500 focus:border-red-500"
                  required
                />
              </div>
              <div className="text-center">
                <button
                  type="submit"
                  className="bg-red-600 text-white py-3 px-8 rounded-lg font-semibold hover:bg-red-700 transition duration-200"
                >
                  Enroll Now
                </button>
                <p className="text-sm text-gray-600 mt-2">
                  For course details and pricing, call us at +91 7889093147
                </p>
              </div>
            </form>
          </div>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default LaserDentistryCourse;
